#include "MixAnalysis.h"
#include "ProjectAssets.h"
#include <cmath>
namespace pulse {
using namespace juce;
namespace {
double db(double value){return value>1e-8?20*std::log10(value):-160;}
Result signatures(const Project& p,const File& base,AssetFingerprints& output,const std::atomic<bool>* cancel){
    AssetFingerprints found;int64 total=0;for(const auto& row:projectAssets(p,base)){if(row.file==File())continue;if(cancel&&cancel->load())return Result::fail("Mix analysis cancelled.");auto size=row.file.getSize();if(size<0||size>maxFingerprintPassBytes-total)return Result::fail("Mix analysis exceeds the 2 GiB source verification budget.");total+=size;AssetFingerprint fingerprint;auto valid=fingerprintAssetFile(row.file,fingerprint,cancel);if(valid.failed())return valid;found.push_back(std::move(fingerprint));}output=std::move(found);return Result::ok();
}
}
bool MixMeter::feed(float left,float right){
    if(!std::isfinite(left)||!std::isfinite(right))return false;float values[]={left,right};for(int ch=0;ch<2;++ch){double value=values[ch];power[(size_t)ch]+=value*value;peaks[(size_t)ch]=jmax(peaks[(size_t)ch],std::abs(value));clipped[(size_t)ch]+=std::abs(value)>=1;work[(size_t)ch][(size_t)at]=values[ch];}double dx=(double)left-mean[0],dy=(double)right-mean[1];++count;mean[0]+=dx/(double)count;mean[1]+=dy/(double)count;variance[0]+=dx*((double)left-mean[0]);variance[1]+=dy*((double)right-mean[1]);cross+=dx*((double)right-mean[1]);if(++at==2048){spectrum();at=0;}return true;
}
void MixMeter::spectrum(){
    for(int ch=0;ch<2;++ch){auto& data=work[(size_t)ch];double offset=0;for(int i=0;i<at;++i)offset+=data[(size_t)i];if(at)offset/=at;double scale=1;for(int i=0;i<at;++i)scale=jmax(scale,std::abs((double)data[(size_t)i]-offset));for(int i=0;i<2048;++i)data[(size_t)i]=i<at?(float)(((data[(size_t)i]-offset)/scale)*(.5-.5*std::cos(2*MathConstants<double>::pi*i/2047))):0;std::fill(data.begin()+2048,data.end(),0.f);fft.performFrequencyOnlyForwardTransform(data.data());for(int bin=1;bin<1024;++bin){double hz=bin*48000./2048;if(hz<20||hz>=20000)continue;int band=hz<200?0:hz<4000?1:2;double magnitude=data[(size_t)bin];bands[(size_t)band]+=magnitude*magnitude*scale*scale;}}
}
MixMeasurements MixMeter::finish(){
    if(at){spectrum();at=0;}MixMeasurements result;result.frames=count;result.peak=peaks;result.fullScale=clipped;if(!count)return result;double n=(double)count;for(int ch=0;ch<2;++ch){result.rms[(size_t)ch]=std::sqrt(power[(size_t)ch]/n);result.dc[(size_t)ch]=mean[(size_t)ch];}double l=jmax(0.,variance[0]),r=jmax(0.,variance[1]);result.correlationValid=l>n*1e-16&&r>n*1e-16;if(result.correlationValid)result.correlation=jlimit(-1.,1.,cross/std::sqrt(l*r));double total=bands[0]+bands[1]+bands[2];if(total>0)for(int i=0;i<3;++i)result.bandFraction[(size_t)i]=bands[(size_t)i]/total;return result;
}
String mixProjectHash(const Project& project,const File& base){auto text=JSON::toString(projectToJson(absoluteAssets(project,base)),false,22);return SHA256(text.toRawUTF8(),(size_t)text.getNumBytesAsUTF8()).toHexString();}
bool sameMixAssets(const AssetFingerprints& a,const AssetFingerprints& b){if(a.size()!=b.size())return false;for(size_t i=0;i<a.size();++i)if(a[i].path!=b[i].path||a[i].hash!=b[i].hash||a[i].bytes!=b[i].bytes)return false;return true;}
Result analyzeMix(const Project& project,const File& base,MixAnalysisReport& output,std::atomic<bool>* cancel,std::atomic<float>* progress){
    if(progress)progress->store(0);auto cancelled=[&]{return cancel&&cancel->load();};if(cancelled())return Result::fail("Mix analysis cancelled.");Project checked;auto valid=projectFromJson(projectToJson(project),checked);if(valid.failed())return valid;
    RenderSettings settings;settings.bits=32;RenderPlan plan;valid=planRender(project,settings,plan);if(valid.failed())return valid;if(plan.outputFrames>48000*600LL)return Result::fail("Offline mix analysis is limited to ten minutes including its two-second tail. Analyze a shorter current pattern or arrangement.");
    MixAnalysisReport report;report.title=project.title;report.songMode=plan.songMode;report.projectHash=mixProjectHash(project,base);valid=signatures(project,base,report.assets,cancel);if(valid.failed())return valid;if(progress)progress->store(.05f);
    Assets assets;auto engine=std::make_unique<Engine>();auto p=project;p.loop=false;p.metronome=false;String warnings;auto& state=engine->exchange.beginWrite();valid=compilePlayback(p,assets,base,state,warnings);if(valid.failed())return valid;if(warnings.isNotEmpty())return Result::fail("Resolve source audio before mix analysis:\n"+warnings);
    state.length=plan.endBeat;while(state.eventCount&&state.events[(size_t)state.eventCount-1].beat>=plan.endBeat)--state.eventCount;for(int i=0;i<state.eventCount;++i)state.events[(size_t)i].length=jmin(state.events[(size_t)i].length,plan.endBeat-state.events[(size_t)i].beat);
    engine->preserveAutomationInTails=true;engine->exchange.publish();engine->prepare(48000);engine->playing.store(true);AudioBuffer<float> block(2,512);auto meter=std::make_unique<MixMeter>();auto total=plan.endFrame+plan.tailFrames;
    for(int64 pos=0;pos<total;){if(cancelled())return Result::fail("Mix analysis cancelled.");int size=(int)jmin((int64)512,total-pos);if(pos<plan.endFrame)size=(int)jmin((int64)size,plan.endFrame-pos);else engine->playing.store(false);engine->render(block.getWritePointer(0),block.getWritePointer(1),size);for(int i=0;i<size;++i)if(!meter->feed(block.getSample(0,i),block.getSample(1,i)))return Result::fail("Mix analysis found non-finite rendered audio.");pos+=size;if(progress)progress->store(.05f+.85f*(float)((double)pos/total));}
    report.measured=meter->finish();AssetFingerprints after;valid=signatures(project,base,after,cancel);if(valid.failed())return valid;if(!sameMixAssets(report.assets,after))return Result::fail("Source audio changed during analysis. Analyze again.");if(cancelled())return Result::fail("Mix analysis cancelled.");
    report.masterBefore=report.masterAfter=project.master;double peak=jmax(report.measured.peak[0],report.measured.peak[1]),ceiling=std::pow(10.,-1./20);bool automated=false;for(const auto& c:project.clips)automated|=c.isAutomation()&&c.automationTarget==5;
    if(peak<1e-8)report.levelReason="No audible output measured. Check notes, clips, mute/solo and routing.";
    else if(project.masterSoftClip)report.levelReason="Master saturation is active. Review its gain staging before choosing a level correction.";
    else if(automated)report.levelReason="Master-gain automation is present. Edit its curve; changing the base Master gain may be overridden.";
    else if(peak>ceiling*1.0001){report.masterAfter=(float)(project.master*ceiling/peak);report.canReduce=report.masterAfter>0&&report.masterAfter<project.master;if(report.canReduce)report.reductionDb=-20*std::log10(report.masterAfter/project.master);report.levelReason=report.canReduce?"Reduce the base Master gain to a -1 dBFS sample-peak ceiling. Apply first verifies the proposed rendering and original source bytes.":"Signal exceeds the supported gain-correction range. Reduce source levels manually.";}
    else report.levelReason="No reduction to a -1 dBFS sample-peak ceiling is needed.";
    output=std::move(report);if(progress)progress->store(1);return Result::ok();
}
String mixAnalysisText(const MixAnalysisReport& report){
    const auto& m=report.measured;double peak=jmax(m.peak[0],m.peak[1]),rms=std::sqrt((m.rms[0]*m.rms[0]+m.rms[1]*m.rms[1])*.5);String text="Offline "+String(report.songMode?"Song":"Pattern")+" snapshot: "+report.title+"\n48 kHz stereo / "+String(m.frames/48000.,2)+" seconds including two-second tail\n\n";
    text+="Sample peak L / R: "+String(db(m.peak[0]),2)+" / "+String(db(m.peak[1]),2)+" dBFS\nRMS L / R: "+String(db(m.rms[0]),2)+" / "+String(db(m.rms[1]),2)+" dBFS\nFull-scale samples L / R: "+String((int64)m.fullScale[0])+" / "+String((int64)m.fullScale[1])+"\nDC offset L / R: "+String(m.dc[0],6)+" / "+String(m.dc[1],6)+"\nStereo correlation: "+(m.correlationValid?String(m.correlation,3):String("unavailable (silence/constant or one-sided signal)"))+"\nCrest factor: "+String(jmax(0.,db(peak)-db(rms)),2)+" dB\n\nFFT power balance (20 Hz-20 kHz):\n20-200 Hz: "+String(m.bandFraction[0]*100,1)+"% / 200-4000 Hz: "+String(m.bandFraction[1]*100,1)+"% / 4-20 kHz: "+String(m.bandFraction[2]*100,1)+"%\n\n";
    if(m.fullScale[0]+m.fullScale[1])text+="Samples reach/exceed full scale; integer exports can clip without level control.\n";if(m.correlationValid&&m.correlation<-.25)text+="Negative stereo correlation: audition in mono and check polarity/width.\n";if(std::abs(m.dc[0])>.01||std::abs(m.dc[1])>.01)text+="DC offset exceeds 1%: inspect the source and gain staging.\n";if(peak>1e-8&&db(rms)<-35)text+="Low average level; this can reflect intentional silence or dynamics.\n";
    text+="\n"+report.levelReason;if(report.canReduce)text+="\nProposed reduction: "+String(report.reductionDb,2)+" dB; Master "+String(report.masterBefore,6)+" -> "+String(report.masterAfter,6)+".";text+="\n\nThese are sample-peak/RMS and unweighted FFT measurements, not LUFS or true peak. Balance is descriptive, not a genre target. Live inputs, click and Browser preview are excluded. No automatic EQ or dynamics changes.";return text;
}
var mixAnalysisToJson(const MixAnalysisReport& report){
    auto* o=new DynamicObject();o->setProperty("schema",1);o->setProperty("application","Pulse Studio mix analysis");o->setProperty("algorithm","pulse-mix-1 / stereo FFT2048 Hann / sample peak and RMS");o->setProperty("sampleRate",48000);o->setProperty("tailSeconds",2);o->setProperty("projectHash",report.projectHash);o->setProperty("title",report.title);o->setProperty("songMode",report.songMode);o->setProperty("frames",(int64)report.measured.frames);o->setProperty("durationSeconds",report.measured.frames/48000.);auto array=[](const auto& values){Array<var> out;for(auto v:values)out.add(var(v));return var(out);};o->setProperty("peak",array(report.measured.peak));o->setProperty("rms",array(report.measured.rms));o->setProperty("dc",array(report.measured.dc));Array<var> clipped;for(auto n:report.measured.fullScale)clipped.add((int64)n);o->setProperty("fullScaleSamples",clipped);o->setProperty("bandFraction",array(report.measured.bandFraction));o->setProperty("correlation",report.measured.correlation);o->setProperty("correlationValid",report.measured.correlationValid);o->setProperty("canReduce",report.canReduce);o->setProperty("masterBefore",report.masterBefore);o->setProperty("masterAfter",report.masterAfter);o->setProperty("reductionDb",report.reductionDb);o->setProperty("levelReason",report.levelReason);o->setProperty("summary",mixAnalysisText(report));Array<var> assets;for(const auto& a:report.assets){auto* row=new DynamicObject();row->setProperty("path",a.path);row->setProperty("sha256",a.hash);row->setProperty("bytes",a.bytes);assets.add(var(row));}o->setProperty("assets",assets);return var(o);
}
Result saveMixAnalysisReport(const File& file,const MixAnalysisReport& report){
    const auto& m=report.measured;bool validNumbers=m.frames>0&&m.frames<=48000*600ULL&&std::isfinite(m.correlation)&&std::abs(m.correlation)<=1&&std::isfinite(report.masterBefore)&&std::isfinite(report.masterAfter)&&std::isfinite(report.reductionDb)&&report.masterBefore>=0&&report.masterBefore<=1&&report.masterAfter>=0&&report.masterAfter<=1&&report.reductionDb>=0;
    for(int c=0;c<2;++c)validNumbers&=std::isfinite(m.peak[c])&&m.peak[c]>=0&&std::isfinite(m.rms[c])&&m.rms[c]>=0&&m.rms[c]<=m.peak[c]+1e-6&&std::isfinite(m.dc[c])&&std::abs(m.dc[c])<=m.peak[c]+1e-6&&m.fullScale[c]<=m.frames;
    for(auto fraction:m.bandFraction)validNumbers&=std::isfinite(fraction)&&fraction>=0&&fraction<=1;
    if(!validNumbers||report.projectHash.length()!=64||report.assets.size()>maxAssetFingerprints)return Result::fail("Invalid mix report. Previous report retained.");
    auto text=JSON::toString(mixAnalysisToJson(report),false,22);if(text.getNumBytesAsUTF8()>1024*1024)return Result::fail("Mix report exceeds 1 MiB.");auto valid=file.getParentDirectory().createDirectory();if(valid.failed())return valid;TemporaryFile temporary(file);if(!temporary.getFile().replaceWithText(text)||temporary.getFile().loadFileAsString()!=text||!temporary.overwriteTargetFileWithTemporary())return Result::fail("Could not save the mix analysis report. Previous report retained.");return Result::ok();
}
}
